13	/// showMap 全屏地图覆盖层
14	///
15	/// 当 `active_ui_mode.mode == "show_map"` 时渲染。
16	/// 从资源系统加载 `maps/{map_id}.json`，渲染背景图和位置按钮。
17	#[component]
18	pub fn MapOverlay(render_state: Signal<RenderState>) -> Element {
19	    let app_state = use_context::<AppState>();
20	    let rs = render_state.read();
