1	use dioxus::prelude::*;
2	
3	use crate::render_state::RenderState;
4	
5	/// 资源 URL 构建
6	fn asset_url(path: &str) -> String {
7	    format!("http://ring-asset.localhost/{path}")
8	}
9	
10	/// 音频桥接组件：监听 `AudioRenderState` 变化，通过 JS Web Audio API 播放。
11	///
12	/// 不渲染任何 DOM。在 mount 时注入 JS `AudioManager`，
13	/// 每帧 diff BGM/SFX 状态并调用 JS 函数。
14	#[component]
15	pub fn AudioBridge(render_state: Signal<RenderState>) -> Element {
16	    // 注入 JS 音频管理器（仅首次 mount）
17	    use_effect(|| {
18	        document::eval(
19	            r#"
20	            window.__ringAudio = (function() {
21	                let bgmAudio = null;
22	                let bgmPath = null;
23	                let bgmFadeInterval = null;
24	
25	                function stopBgmFade() {
26	                    if (bgmFadeInterval) {
27	                        clearInterval(bgmFadeInterval);
28	                        bgmFadeInterval = null;
29	                    }
30	                }
31	
32	                function fadeBgmTo(targetVol, duration, onDone) {
33	                    stopBgmFade();
34	                    if (!bgmAudio || duration <= 0) {
35	                        if (bgmAudio) bgmAudio.volume = Math.max(0, Math.min(1, targetVol));
36	                        if (onDone) onDone();
37	                        return;
38	                    }
39	                    const startVol = bgmAudio.volume;
40	                    const steps = Math.max(1, Math.round(duration * 30));
41	                    const delta = (targetVol - startVol) / steps;
42	                    let step = 0;
43	                    bgmFadeInterval = setInterval(() => {
44	                        step++;
45	                        if (step >= steps) {
46	                            bgmAudio.volume = Math.max(0, Math.min(1, targetVol));
47	                            stopBgmFade();
48	                            if (onDone) onDone();
49	                        } else {
50	                            bgmAudio.volume = Math.max(0, Math.min(1, startVol + delta * step));
51	                        }
52	                    }, (duration * 1000) / steps);
53	                }
54	
55	                return {
56	                    playBgm(url, loop_, volume, fadeDuration) {
57	                        if (bgmPath === url) {
58	                            // same track, just update volume
59	                            if (bgmAudio) {
60	                                const v = Math.max(0, Math.min(1, volume));
61	                                if (fadeDuration > 0) {
62	                                    fadeBgmTo(v, fadeDuration);
63	                                } else {
64	                                    stopBgmFade();
65	                                    bgmAudio.volume = v;
66	                                }
67	                            }
68	                            return;
69	                        }
70	                        // different track: crossfade
71	                        const oldAudio = bgmAudio;
72	                        const newAudio = new Audio(url);
73	                        newAudio.loop = loop_;
74	                        newAudio.volume = 0;
75	                        bgmAudio = newAudio;
76	                        bgmPath = url;
77	
78	                        newAudio.play().catch(e => console.warn("[audio] BGM play failed:", e));
79	
80	                        const targetVol = Math.max(0, Math.min(1, volume));
81	                        const fd = fadeDuration > 0 ? fadeDuration : 0.5;
82	
83	                        // Fade in new
84	                        fadeBgmTo(targetVol, fd);
85	
86	                        // Fade out old
87	                        if (oldAudio) {
88	                            const oldSteps = Math.max(1, Math.round(fd * 30));
89	                            const oldStart = oldAudio.volume;
90	                            const oldDelta = oldStart / oldSteps;
91	                            let oldStep = 0;
92	                            const oldFade = setInterval(() => {
93	                                oldStep++;
94	                                if (oldStep >= oldSteps) {
95	                                    oldAudio.pause();
96	                                    oldAudio.src = "";
97	                                    clearInterval(oldFade);
98	                                } else {
99	                                    oldAudio.volume = Math.max(0, oldStart - oldDelta * oldStep);
100	                                }
101	                            }, (fd * 1000) / oldSteps);
102	                        }
103	                    },
104	
105	                    stopBgm(fadeDuration) {
106	                        if (!bgmAudio) return;
107	                        const fd = fadeDuration > 0 ? fadeDuration : 0;
108	                        if (fd > 0) {
109	                            fadeBgmTo(0, fd, () => {
110	                                if (bgmAudio) { bgmAudio.pause(); bgmAudio.src = ""; }
111	                                bgmAudio = null;
112	                                bgmPath = null;
113	                            });
114	                        } else {
115	                            stopBgmFade();
116	                            bgmAudio.pause();
117	                            bgmAudio.src = "";
118	                            bgmAudio = null;
119	                            bgmPath = null;
120	                        }
121	                    },
122	
123	                    setBgmVolume(volume) {
124	                        if (bgmAudio) {
125	                            bgmAudio.volume = Math.max(0, Math.min(1, volume));
126	                        }
127	                    },
128	
129	                    playSfx(url, volume) {
130	                        const audio = new Audio(url);
131	                        audio.volume = Math.max(0, Math.min(1, volume));
132	                        audio.play().catch(e => console.warn("[audio] SFX play failed:", e));
133	                    }
134	                };
135	            })();
136	            console.log("[audio] JS AudioManager initialized");
137	        "#,
138	        );
139	    });
140	
141	    // 跟踪上一帧的 BGM 状态，用于 diff
142	    let mut prev_bgm_path = use_signal(|| Option::<String>::None);
143	    let mut prev_bgm_volume = use_signal(|| 0.0f32);
144	
145	    // 每帧检查音频状态变化
146	    let audio_memo = use_memo(move || render_state.read().audio.clone());
147	    let audio = audio_memo.read();
148	
149	    // 处理 BGM 变化
150	    let current_bgm = &audio.bgm;
151	    let transition = &audio.bgm_transition;
152	    let fade_duration = transition.as_ref().map_or(0.0, |t| t.duration);
153	
154	    match current_bgm {
155	        Some(bgm) => {
156	            let url = asset_url(&bgm.path);
157	            let prev_path = prev_bgm_path.read().clone();
158	            let prev_vol = *prev_bgm_volume.read();
159	
160	            if prev_path.as_deref() != Some(&url) {
161	                // BGM changed
162	                let looping = bgm.looping;
163	                let volume = bgm.volume;
164	                document::eval(&format!(
165	                    r#"if(window.__ringAudio) window.__ringAudio.playBgm("{url}", {looping}, {volume}, {fade_duration});"#
166	                ));
167	                prev_bgm_path.set(Some(url));
168	                prev_bgm_volume.set(volume);
169	            } else if (bgm.volume - prev_vol).abs() > 0.5 {
170	                // Volume changed significantly
171	                let volume = bgm.volume;
172	                document::eval(&format!(
173	                    "if(window.__ringAudio) window.__ringAudio.setBgmVolume({volume});"
174	                ));
175	                prev_bgm_volume.set(volume);
176	            }
177	        }
178	        None => {
179	            if prev_bgm_path.read().is_some() {
180	                // BGM stopped
181	                document::eval(&format!(
182	                    "if(window.__ringAudio) window.__ringAudio.stopBgm({fade_duration});"
183	                ));
184	                prev_bgm_path.set(None);
185	                prev_bgm_volume.set(0.0);
186	            }
187	        }
188	    }
189	
190	    // 处理 SFX 队列（drain 语义——每帧只出现一次）
191	    for sfx in &audio.sfx_queue {
192	        let url = asset_url(&sfx.path);
193	        let volume = sfx.volume;
194	        document::eval(&format!(
195	            r#"if(window.__ringAudio) window.__ringAudio.playSfx("{url}", {volume});"#
196	        ));
197	    }
198	
199	    // 不渲染任何 DOM
200	    rsx! {}
201	}
202

