344	    pub fn advance_typewriter(&mut self) -> bool {
345	        let Some(d) = self.dialogue.as_mut() else {
346	            return true;
347	        };
348	        if d.is_complete {
349	            return true;
350	        }
351	
352	        d.visible_chars += 1;
353	
354	        for effect in &d.inline_effects {
355	            if effect.position == d.visible_chars {
356	                match &effect.kind {
357	                    InlineEffectKind::Wait(duration) => {
358	                        d.inline_wait = Some(match *duration {
359	                            Some(t) => InlineWait::Timed { remaining: t },
360	                            None => InlineWait::Click,
361	                        });
362	                    }
363	                    InlineEffectKind::SetCpsAbsolute(cps) => {
364	                        d.effective_cps = Some(EffectiveCps::Absolute(*cps));
365	                    }
366	                    InlineEffectKind::SetCpsRelative(multiplier) => {
367	                        d.effective_cps = Some(EffectiveCps::Relative(*multiplier));
368	                    }
369	                    InlineEffectKind::ResetCps => {
370	                        d.effective_cps = None;
371	                    }
372	                }
373	            }
374	        }
375	
376	        let total = d.content.chars().count();
377	        if d.visible_chars >= total {
378	            d.is_complete = true;
379	        }
380	        let complete = d.is_complete;
381	        let visible = d.visible_chars;
382	
383	        if let Some(entry) = self.nvl_entries.last_mut() {
384	            entry.visible_chars = visible;
385	            entry.is_complete = complete;
386	        }
387	
388	        complete
389	    }
