499	        };
500	        cm.timer += dt;
501	        match cm.phase {
502	            ChapterMarkPhase::FadeIn => {
503	                cm.alpha = (cm.timer / CHAPTER_MARK_FADE_IN).min(1.0);
504	                if cm.timer >= CHAPTER_MARK_FADE_IN {
505	                    cm.phase = ChapterMarkPhase::Visible;
506	                    cm.timer = 0.0;
507	                    cm.alpha = 1.0;
508	                }
509	                false
510	            }
511	            ChapterMarkPhase::Visible => {
512	                if cm.timer >= CHAPTER_MARK_VISIBLE {
513	                    cm.phase = ChapterMarkPhase::FadeOut;
514	                    cm.timer = 0.0;
515	                }
516	                false
517	            }
518	            ChapterMarkPhase::FadeOut => {
519	                cm.alpha = 1.0 - (cm.timer / CHAPTER_MARK_FADE_OUT).min(1.0);
520	                if cm.timer >= CHAPTER_MARK_FADE_OUT {
521	                    self.chapter_mark = None;
522	                    return true;
523	                }
524	                false
525	            }
526	        }
527	    }
