#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct CharacterSprite {
    pub texture_path: String,
    pub position: Position,
    pub z_order: i32,
    pub fading_out: bool,
    pub alpha: f32,
    pub offset_x: f32,
    pub offset_y: f32,
    pub scale_x: f32,
    pub scale_y: f32,
    pub transition_duration: Option<f32>,
    pub target_alpha: f32,
    pub pos_x: f32,
    pub pos_y: f32,
