#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct SceneTransition {
    pub transition_type: SceneTransitionKind,
    pub phase: SceneTransitionPhaseState,
    pub duration: f32,
    pub pending_background: Option<String>,
