#[derive(Debug, Clone, Serialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum InlineWait {
    Click,
    Timed { remaining: f64 },
}

#[derive(Debug, Clone, Serialize)]
pub enum EffectiveCps {
    Absolute(f64),
    Relative(f64),
