258	    fn execute_background(&self, cmd: &Command, rs: &mut RenderState) -> ExecuteResult {
259	        match cmd {
260	            Command::ShowBackground {
261	                path, transition, ..
262	            } => {
263	                if let Some(t) = transition {
264	                    let (kind, duration) = resolve_transition(t);
265	                    if let TransitionKind::None = kind {
266	                        rs.set_background(path.clone());
267	                    } else {
268	                        rs.background_transition = Some(BackgroundTransition {
269	                            old_background: rs.current_background.clone(),
270	                            new_background: path.clone(),
271	                            duration,
272	                        });
273	                        rs.set_background(path.clone());
274	                    }
275	                } else {
276	                    rs.set_background(path.clone());
277	                }
278	                ExecuteResult::Ok
279	            }
280	            Command::ChangeScene {
281	                path, transition, ..
282	            } => {
283	                if let Some(t) = transition {
284	                    let (kind, duration) = resolve_transition(t);
285	                    match kind {
286	                        TransitionKind::Dissolve | TransitionKind::Move => {
287	                            rs.background_transition = Some(BackgroundTransition {
288	                                old_background: rs.current_background.clone(),
289	                                new_background: path.clone(),
290	                                duration,
291	                            });
292	                            rs.set_background(path.clone());
293	                        }
294	                        TransitionKind::Fade => {
295	                            rs.scene_transition = Some(SceneTransition {
296	                                transition_type: SceneTransitionKind::Fade,
297	                                phase: SceneTransitionPhaseState::FadeIn,
298	                                duration,
299	                                pending_background: Some(path.clone()),
300	                            });
301	                        }
302	                        TransitionKind::FadeWhite => {
303	                            rs.scene_transition = Some(SceneTransition {
304	                                transition_type: SceneTransitionKind::FadeWhite,
305	                                phase: SceneTransitionPhaseState::FadeIn,
306	                                duration,
307	                                pending_background: Some(path.clone()),
308	                            });
309	                        }
310	                        TransitionKind::Rule {
311	                            mask_path,
312	                            reversed,
313	                            ramp,
314	                        } => {
315	                            rs.scene_transition = Some(SceneTransition {
316	                                transition_type: SceneTransitionKind::Rule {
317	                                    mask_path,
318	                                    reversed,
319	                                    ramp,
320	                                },
321	                                phase: SceneTransitionPhaseState::FadeIn,
322	                                duration,
323	                                pending_background: Some(path.clone()),
324	                            });
325	                        }
326	                        TransitionKind::None => rs.set_background(path.clone()),
327	                    }
328	                } else {
329	                    rs.set_background(path.clone());
330	                }
331	                ExecuteResult::Ok
332	            }
333	            _ => unreachable!("execute_background: unexpected command"),
334	        }
335	    }
336	
337	    // ── 立绘 ─────────────────────────────────────────────────────────────────
338	
339	    fn execute_character(
340	        &self,
341	        cmd: &Command,
342	        rs: &mut RenderState,
343	        manifest: &Manifest,
344	    ) -> ExecuteResult {
345	        match cmd {
346	            Command::ShowCharacter {
347	                path,
348	                alias,
349	                position,
350	                transition,
351	            } => {
352	                let (kind, duration) = transition
353	                    .as_ref()
354	                    .map_or((TransitionKind::None, 0.0), resolve_transition);
355	
356	                let preset_name = crate::render_state::position_to_preset_name(*position);
357	                let preset = manifest.get_preset(preset_name);
358	                let group = manifest.get_group_config(path);
359	
360	                if let Some(c) = rs.visible_characters.get_mut(alias) {
361	                    let is_position_change = c.position != *position;
362	                    let is_same_texture = c.texture_path == *path;
363	
364	                    c.texture_path.clone_from(path);
365	                    c.position = *position;
366	                    c.target_alpha = 1.0;
367	                    c.pos_x = preset.x;
368	                    c.pos_y = preset.y;
369	                    c.anchor_x = group.anchor.x;
370	                    c.anchor_y = group.anchor.y;
371	                    c.render_scale = group.pre_scale * preset.scale;
372	
373	                    if is_position_change && matches!(kind, TransitionKind::Move) {
374	                        c.transition_duration = Some(duration);
375	                    } else if is_same_texture && is_position_change {
376	                        c.transition_duration = None;
377	                        c.alpha = 1.0;
378	                    } else {
379	                        c.transition_duration = if matches!(kind, TransitionKind::None) {
380	                            c.alpha = 1.0;
381	                            None
382	                        } else {
383	                            Some(duration)
384	                        };
385	                    }
386	                } else {
387	                    let (start_alpha, trans_dur) = if matches!(kind, TransitionKind::None) {
388	                        (1.0, None)
389	                    } else {
390	                        (0.0, Some(duration))
391	                    };
392	                    rs.show_character(alias.clone(), path.clone(), *position, manifest);
393	                    if let Some(c) = rs.visible_characters.get_mut(alias) {
394	                        c.transition_duration = trans_dur;
395	                        c.alpha = start_alpha;
396	                        c.target_alpha = 1.0;
397	                    }
398	                }
399	                ExecuteResult::Ok
400	            }
401	            Command::HideCharacter { alias, transition } => {
402	                if let Some(t) = transition {
403	                    let (_, duration) = resolve_transition(t);
404	                    if let Some(c) = rs.visible_characters.get_mut(alias) {
405	                        c.transition_duration = Some(duration);
406	                        c.target_alpha = 0.0;
407	                        c.fading_out = true;
408	                    }
409	                } else {
410	                    rs.hide_character(alias);
411	                }
412	                ExecuteResult::Ok
413	            }
414	            Command::ClearCharacters => {
415	                rs.hide_all_characters();
416	                ExecuteResult::Ok
417	            }
418	            _ => unreachable!("execute_character: unexpected command"),
419	        }
420	    }
