447	            }
448	            Command::ExtendText {
449	                content,
450	                inline_effects,
451	                no_wait,
452	            } => {
453	                rs.extend_dialogue(content, inline_effects.clone(), *no_wait);
454	                ExecuteResult::WaitForClick
455	            }
456	            Command::TextBoxHide => {
457	                rs.ui_visible = false;
458	                ExecuteResult::Ok
459	            }
460	            Command::TextBoxShow => {
461	                rs.ui_visible = true;
462	                ExecuteResult::Ok
463	            }
464	            Command::TextBoxClear => {
465	                rs.clear_dialogue();
466	                ExecuteResult::Ok
467	            }
468	            Command::SetTextMode(mode) => {
469	                if *mode == TextMode::ADV {
470	                    rs.nvl_entries.clear();
471	                }
472	                rs.text_mode = *mode;
