479	    // ── 选项 ─────────────────────────────────────────────────────────────────
480	
481	    fn execute_choices(&self, cmd: &Command, rs: &mut RenderState) -> ExecuteResult {
482	        let Command::PresentChoices { choices, style } = cmd else {
483	            unreachable!("execute_choices: unexpected command");
484	        };
485	        rs.clear_dialogue();
486	        let items = choices
487	            .iter()
488	            .map(|c| ChoiceItem {
489	                text: c.text.clone(),
