498	
499	    // ── 音频 ─────────────────────────────────────────────────────────────────
500	
501	    fn execute_audio(&mut self, cmd: &Command) -> ExecuteResult {
502	        self.last_output.audio_command = Some(match cmd {
503	            Command::PlayBgm { path, looping } => AudioCommand::PlayBgm {
504	                path: path.clone(),
505	                looping: *looping,
506	                fade_in: None,
507	            },
508	            Command::StopBgm { fade_out } => AudioCommand::StopBgm {
509	                fade_out: fade_out.map(|f| f as f32),
510	            },
511	            Command::BgmDuck => AudioCommand::BgmDuck,
512	            Command::BgmUnduck => AudioCommand::BgmUnduck,
513	            Command::PlaySfx { path } => AudioCommand::PlaySfx { path: path.clone() },
514	            _ => unreachable!("execute_audio: unexpected command"),
515	        });
516	        ExecuteResult::Ok
