518	
519	    // ── 演出效果 ─────────────────────────────────────────────────────────────
520	
521	    fn execute_effects(&self, cmd: &Command, rs: &mut RenderState) -> ExecuteResult {
522	        match cmd {
523	            Command::ChapterMark { title, level } => {
524	                rs.set_chapter_mark(title.clone(), *level);
525	                ExecuteResult::Ok
526	            }
527	            Command::TitleCard { text, duration } => {
528	                rs.title_card = Some(crate::render_state::TitleCardState {
529	                    text: text.clone(),
530	                    duration: *duration as f32,
531	                    elapsed: 0.0,
532	                });
533	                ExecuteResult::Ok
534	            }
535	            _ => unreachable!("execute_effects: unexpected command"),
536	        }
537	    }
538	
539	    fn execute_scene_effect(&mut self, cmd: &Command) -> ExecuteResult {
540	        let Command::SceneEffect { name, args } = cmd else {
541	            unreachable!("execute_scene_effect: unexpected command");
542	        };
543	        self.last_output.scene_effect_request = Some(SceneEffectRequest::from_command(name, args));
544	        ExecuteResult::Ok
545	    }
546	
547	    // ── 流程控制 ─────────────────────────────────────────────────────────────
548	
549	    fn execute_control(&self, cmd: &Command) -> ExecuteResult {
550	        match cmd {
551	            Command::Cutscene { path } => ExecuteResult::WaitForCutscene {
552	                video_path: path.clone(),
553	            },
554	            Command::FullRestart => ExecuteResult::FullRestart,
555	            Command::RequestUI { key, mode, params } => ExecuteResult::RequestUI {
556	                key: key.clone(),
557	                mode: mode.clone(),
558	                params: params.clone(),
559	            },
560	            _ => unreachable!("execute_control: unexpected command"),
561	        }
562	    }
563	
564	    pub fn execute_batch(
565	        &mut self,
566	        cmds: &[Command],
567	        rs: &mut RenderState,
568	        manifest: &Manifest,
569	    ) -> BatchOutput {
570	        let mut final_result = ExecuteResult::Ok;
571	        let mut audio_commands = Vec::new();
572	        let mut scene_effect_request = None;
573	        for cmd in cmds {
574	            let result = self.execute(cmd, rs, manifest);
575	            if let Some(audio) = self.last_output.audio_command.take() {
576	                audio_commands.push(audio);
577	            }
578	            if let Some(effect) = self.last_output.scene_effect_request.take() {
579	                scene_effect_request = Some(effect);
580	            }
581	            if result != ExecuteResult::Ok {
582	                final_result = result;
583	            }
584	        }
585	        BatchOutput {
586	            result: final_result,
587	            audio_commands,
588	            scene_effect_request,
589	        }
590	    }
591	}
