#[cfg(not(target_arch = "wasm32"))]
pub mod debug_server;

// ── 前端模块（Phase 2） ──
mod components;
mod screens;
mod vn;

use std::{
    borrow::Cow,
    sync::{Arc, Mutex, OnceLock},
    time::Duration,
};

/// 获取当前 Unix 时间戳（秒）
///
/// Host 侧唯一的时间源，用于为 Runtime 注入时间戳。
/// Desktop 使用 `SystemTime`，WASM 使用 `js_sys::Date`。
pub fn now_secs() -> u64 {
    #[cfg(not(target_arch = "wasm32"))]
    {
        use std::time::{SystemTime, UNIX_EPOCH};
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map_or(0, |d| d.as_secs())
    }
    #[cfg(target_arch = "wasm32")]
    {
        (js_sys::Date::now() / 1000.0) as u64
    }
}

use components::{ConfirmDialog, PendingConfirm, SkipIndicator, ToastLayer, ToastQueue};
use dioxus::{
    desktop::{
        Config,
        tao::{dpi::LogicalSize, window::WindowBuilder},
        wry::http,
    },
    prelude::*,
};
use render_state::{HostScreen, RenderState};
use resources::{LogicalPath, ResourceManager};
use screens::{HistoryScreen, InGameMenu, SaveLoadScreen, SettingsScreen, TitleScreen};
use state::{AppState, AppStateInner};
use tracing::{error, info};
use vn::VNScene;

/// 全局 ResourceManager，在 `init::initialize_inner()` 中初始化。
///
/// `ring_asset_handler` 通过此静态访问资源（自动适配 `FsSource` / `ZipSource`）。
/// 必须在 `initialize_inner` 完成前设置，否则 handler 返回 503。
pub(crate) static RESOURCE_MANAGER: OnceLock<Arc<ResourceManager>> = OnceLock::new();

// ---------------------------------------------------------------------------
// 全局 CSS（BEM 命名，编译时嵌入，完整内容见 global.css）
// ---------------------------------------------------------------------------

const GLOBAL_CSS: &str = include_str!("global.css");

