80	const GLOBAL_CSS: &str = include_str!("global.css");
81	
82	// ---------------------------------------------------------------------------
83	// Entry point
84	// ---------------------------------------------------------------------------
85	
86	/// JS 脚本：窗口 resize 时更新 CSS `--scale-factor`。
87	/// 等价于 egui host 的 `ScaleContext.scale_uniform = min(w/1920, h/1080)`。
88	const SCALE_JS: &str = r"
89	<script>
90	(function() {
91	    function updateScale() {
92	        var w = window.innerWidth;
93	        var h = window.innerHeight;
94	        var s = Math.min(w / 1920, h / 1080);
95	        document.documentElement.style.setProperty('--scale-factor', s);
96	    }
97	    window.addEventListener('resize', updateScale);
98	    updateScale();
99	})();
100	</script>
101	";
102	
103	fn main() {
104	    tracing_subscriber::fmt::init();
105	
106	    let css_head = format!("<style>{GLOBAL_CSS}</style>{SCALE_JS}");
107	
108	    dioxus::LaunchBuilder::new()
109	        .with_cfg(
110	            Config::new()
111	                .with_window(
112	                    WindowBuilder::new()
113	                        .with_title("Ring Engine")
114	                        .with_inner_size(LogicalSize::new(1280, 720)),
115	                )
116	                .with_menu(None)
117	                .with_custom_head(css_head)
118	                .with_custom_protocol("ring-asset", ring_asset_handler),
119	        )
120	        .launch(App);
121	}
122	
123	// ---------------------------------------------------------------------------
124	// ring-asset custom protocol handler
125	// ---------------------------------------------------------------------------
126	
127	/// 小游戏完成结果的全局存储。
128	///
129	/// 游戏 iframe 通过 fetch `/__game_complete?result=xxx` 写入，
130	/// `MinigameOverlay` 轮询读取。
131	pub static GAME_COMPLETE_RESULT: std::sync::Mutex<Option<String>> = std::sync::Mutex::new(None);
132	
133	#[expect(
134	    clippy::unwrap_used,
135	    reason = "Response builder infallible with known-good headers"
136	)]
137	#[expect(
138	    clippy::needless_pass_by_value,
139	    reason = "Signature required by Dioxus custom protocol API"
140	)]
141	fn ring_asset_handler(
142	    _id: dioxus::desktop::wry::WebViewId,
143	    request: http::Request<Vec<u8>>,
144	) -> http::Response<Cow<'static, [u8]>> {
145	    let uri = request.uri().to_string();
146	    let raw_path = request.uri().path();
147	    let path_clean = percent_decode(raw_path.trim_start_matches('/'));
148	
149	    // ── 小游戏完成端点（iframe 导航触发） ──
150	    if path_clean.starts_with("__game_complete") {
151	        let query = request.uri().query().unwrap_or("");
152	        let result = query
153	            .split('&')
154	            .find_map(|kv| {
155	                let (k, v) = kv.split_once('=')?;
156	                (k == "result").then(|| percent_decode(v))
157	            })
158	            .unwrap_or_default();
159	        tracing::debug!(result = %result, "game complete via ring-asset");
160	        if let Ok(mut slot) = GAME_COMPLETE_RESULT.lock() {
161	            *slot = Some(result);
162	        }
163	        // 纯黑空页面，与覆盖层背景一致，无视觉闪烁
164	        let body = br#"<!DOCTYPE html><html><body style="background:#000;margin:0"></body></html>"#;
165	        return http::Response::builder()
166	            .status(200)
167	            .header("Content-Type", "text/html")
168	            .body(Cow::from(body.to_vec()))
169	            .unwrap();
170	    }
171	
172	    // ── 虚拟 engine-sdk.js（兼容游戏显式 <script src="../../engine-sdk.js"> 加载） ──
173	    if path_clean == "engine-sdk.js" {
174	        return http::Response::builder()
175	            .status(200)
176	            .header("Content-Type", "application/javascript")
177	            .header("Access-Control-Allow-Origin", "*")
178	            .body(Cow::from(GAME_ENGINE_SDK_JS.as_bytes().to_vec()))
179	            .unwrap();
180	    }
181	
182	    let logical_path = LogicalPath::new(&path_clean);
183	
184	    tracing::debug!(uri = %uri, path = %logical_path, "ring-asset request");
185	
186	    #[expect(
187	        clippy::expect_used,
188	        reason = "uninitialised RM is an engine invariant violation"
189	    )]
190	    let rm = RESOURCE_MANAGER
191	        .get()
192	        .expect("invariant: ResourceManager not yet initialized when ring-asset request arrived");
193	
194	    let mime = guess_mime(&path_clean);
195	
196	    match rm.read_bytes(&logical_path) {
197	        Ok(bytes) => {
198	            // games/*/**.html: 自动注入 engine JS SDK（postMessage 桥接）
199	            let body = if path_clean.starts_with("games/") && mime == "text/html" {
200	                let html = String::from_utf8_lossy(&bytes);
201	                let injected = inject_engine_sdk(&html);
202	                Cow::from(injected.into_bytes())
203	            } else {
204	                Cow::from(bytes)
205	            };
206	            http::Response::builder()
207	                .status(200)
208	                .header("Content-Type", mime)
209	                .header("Access-Control-Allow-Origin", "*")
210	                .body(body)
211	                .unwrap()
212	        }
213	        Err(e) => {
214	            tracing::warn!(path = %logical_path, error = %e, "ring-asset 404");
215	            http::Response::builder()
216	                .status(404)
217	                .header("Content-Type", "text/plain")
218	                .body(Cow::from(format!("Not Found: {logical_path}").into_bytes()))
219	                .unwrap()
220	        }
221	    }
222	}
223	
224	#[expect(
225	    clippy::string_slice,
226	    reason = "slicing ASCII hex pairs at verified byte boundaries"
227	)]
228	fn percent_decode(input: &str) -> String {
229	    let mut out = Vec::with_capacity(input.len());
230	    let bytes = input.as_bytes();
231	    let mut i = 0;
232	    while i < bytes.len() {
233	        if bytes[i] == b'%'
234	            && i + 2 < bytes.len()
235	            && let Ok(byte) = u8::from_str_radix(&input[i + 1..i + 3], 16)
236	        {
237	            out.push(byte);
238	            i += 3;
239	            continue;
240	        }
241	        out.push(bytes[i]);
242	        i += 1;
243	    }
244	    String::from_utf8(out).unwrap_or_else(|_| input.to_string())
245	}
246	
247	fn guess_mime(path: &str) -> &'static str {
248	    match path.rsplit('.').next().unwrap_or("") {
249	        "jpg" | "jpeg" => "image/jpeg",
250	        "png" => "image/png",
251	        "webp" => "image/webp",
252	        "gif" => "image/gif",
253	        "svg" => "image/svg+xml",
254	        "webm" => "video/webm",
255	        "mp4" => "video/mp4",
256	        "mp3" => "audio/mpeg",
257	        "ogg" => "audio/ogg",
258	        "wav" => "audio/wav",
259	        "flac" => "audio/flac",
260	        "css" => "text/css",
261	        "js" => "application/javascript",
262	        "json" => "application/json",
263	        "html" => "text/html",
264	        _ => "application/octet-stream",
265	    }
266	}
267	
268	// ---------------------------------------------------------------------------
269	// Game engine JS SDK injection (for callGame iframe)
270	// ---------------------------------------------------------------------------
271	
272	/// 向游戏 HTML 注入 engine JS SDK。
273	///
274	/// 在 `<head>` 标签后（或文档开头）插入 SDK script。
275	/// SDK 通过 `window.parent.postMessage` 与宿主通信。
276	#[expect(
277	    clippy::string_slice,
278	    reason = "slicing at positions derived from str::find, always char boundaries"
279	)]
280	fn inject_engine_sdk(html: &str) -> String {
281	    let sdk_tag = format!("<script>{GAME_ENGINE_SDK_JS}</script>");
282	    // 在 <head> 后注入，如果没有 <head> 则在开头注入
283	    if let Some(pos) = html.find("<head>") {
284	        let insert_pos = pos + "<head>".len();
285	        format!("{}{sdk_tag}{}", &html[..insert_pos], &html[insert_pos..])
286	    } else if let Some(pos) = html.find("<HEAD>") {
287	        let insert_pos = pos + "<HEAD>".len();
288	        format!("{}{sdk_tag}{}", &html[..insert_pos], &html[insert_pos..])
289	    } else {
290	        format!("{sdk_tag}{html}")
291	    }
292	}
293	
294	/// 同源 fetch-based engine JS SDK。
295	///
296	/// 提供与旧 host HTTP Bridge SDK 兼容的 `window.engine.*` API，
297	/// 内部使用同源 fetch 到 `ring-asset` handler 的虚拟端点通信。
298	///
299	/// 关键路径：`engine.complete(result)` → fetch `/__game_complete?result=xxx`
300	/// → ring-asset handler 存入 static → Rust 轮询读取。
301	const GAME_ENGINE_SDK_JS: &str = r#"
302	(function() {
303	    if (window.engine) return;
304	    window.engine = {
305	        complete: function(result) {
306	            var r = result !== undefined && result !== null ? String(result) : "";
307	            window.location.href = "/__game_complete?result=" + encodeURIComponent(r);
308	        },
309	        onComplete: function(result) {
310	            window.engine.complete(result);
311	        },
312	        playSound: function(name) {
313	            console.log("[engine SDK] playSound: " + name);
314	        },
315	        playBGM: function(name, shouldLoop) {
316	            console.log("[engine SDK] playBGM: " + name);
317	        },
318	        stopBGM: function() {
319	            console.log("[engine SDK] stopBGM");
320	        },
321	        getState: function(key) {
322	            console.warn("[engine SDK] getState not yet supported in iframe mode");
323	            return Promise.resolve(undefined);
324	        },
325	        setState: function(key, value) {
326	            console.warn("[engine SDK] setState not yet supported in iframe mode");
327	            return Promise.resolve();
328	        },
329	        log: function(level, message) {
330	            console.log("[game:" + level + "] " + message);
331	        }
332	    };
333	
334	    // 旧 API 兼容：window.ipc.postMessage 映射
335	    if (!window.ipc) {
336	        window.ipc = {
337	            postMessage: function(jsonStr) {
338	                try {
339	                    var msg = JSON.parse(jsonStr);
340	                    if (msg.type === "onComplete") {
341	                        window.engine.complete(msg.result || msg.data);
342	                    }
343	                } catch(e) {}
344	            }
345	        };
346	    }
347	})();
348	"#;
349	
350	// ---------------------------------------------------------------------------
351	// App 初始化状态
352	// ---------------------------------------------------------------------------
353	
354	#[derive(Clone, PartialEq)]
355	enum InitPhase {
356	    Loading,
357	    Ready,
358	    Error(String),
359	}
360	
361	// ---------------------------------------------------------------------------
362	// Screenshot bridge (debug server ↔ WebView)
363	// ---------------------------------------------------------------------------
364	
365	/// 接收来自 debug HTTP server 的截图请求，通过 `document::eval()` 在 `WebView` 中
366	/// 执行 JS 截图代码，将结果通过 oneshot 通道回传。
367	#[cfg(not(target_arch = "wasm32"))]
368	async fn screenshot_bridge(mut rx: tokio::sync::mpsc::Receiver<debug_server::ScreenshotRequest>) {
369	    while let Some(req) = rx.recv().await {
370	        // 每个请求启动独立 eval，避免阻塞后续请求
371	        spawn(async move {
372	            let mut eval = document::eval(debug_server::SCREENSHOT_JS);
373	            match eval.recv().await {
374	                Ok(msg) => {
375	                    let result: serde_json::Value = msg;
376	                    if let Some(err) = result.get("error").and_then(|v| v.as_str()) {
377	                        // receiver 可能已因超时而被丢弃，忽略发送失败
378	                        let _ = req.reply.send(Err(err.to_string()));
379	                    } else {
380	                        let width = result
381	                            .get("width")
382	                            .and_then(serde_json::Value::as_u64)
383	                            .unwrap_or(1920) as u32;
384	                        let height = result
385	                            .get("height")
386	                            .and_then(serde_json::Value::as_u64)
387	                            .unwrap_or(1080) as u32;
388	                        let data = result
389	                            .get("data")
390	                            .and_then(|v| v.as_str())
391	                            .unwrap_or("")
392	                            .to_string();
393	                        // receiver 可能已因超时而被丢弃，忽略发送失败
394	                        let _ = req.reply.send(Ok(debug_server::ScreenshotData {
395	                            format: "png".to_string(),
396	                            width,
397	                            height,
398	                            data_base64: data,
399	                        }));
400	                    }
401	                }
402	                Err(e) => {
403	                    // receiver 可能已因超时而被丢弃，忽略发送失败
404	                    let _ = req.reply.send(Err(format!("eval 失败: {e}")));
405	                }
406	            }
407	        });
408	    }
409	}
410	
411	// ---------------------------------------------------------------------------
412	// Root component
413	// ---------------------------------------------------------------------------
414	
415	fn App() -> Element {
416	    // 全局 AppState：Arc<Mutex<AppStateInner>>
417	    let app_state = use_context_provider(|| AppState {
418	        inner: Arc::new(Mutex::new(AppStateInner::new())),
419	    });
420	
421	    // 确认弹窗状态（全局 Signal，各页面共享）
422	    let _pending_confirm: Signal<Option<PendingConfirm>> =
423	        use_context_provider(|| Signal::new(None));
424	
425	    // Toast 队列（全局 Signal）
426	    let _toast_queue: Signal<ToastQueue> =
427	        use_context_provider(|| Signal::new(ToastQueue::default()));
428	
429	    // 初始化阶段
430	    let mut init_phase = use_signal(|| InitPhase::Loading);
431	
432	    // RenderState signal：tick loop 每帧更新
433	    let mut render_state = use_signal(RenderState::new);
434	
435	    // 初始化后端子系统（仅首次 mount）
436	    let app_state_init = app_state.clone();
437	    #[expect(
438	        clippy::expect_used,
439	        reason = "Mutex poison means engine panicked; we want to propagate"
440	    )]
441	    use_hook(move || {
442	        spawn(async move {
443	            let result = {
444	                let mut inner = app_state_init
445	                    .inner
446	                    .lock()
447	                    .expect("invariant: app state mutex not poisoned");
448	                init::initialize_inner(&mut inner)
449	            };
450	            match result {
451	                Ok(()) => {
452	                    {
453	                        let mut inner = app_state_init
454	                            .inner
455	                            .lock()
456	                            .expect("invariant: app state mutex not poisoned");
457	                        inner.frontend_connected(Some("dioxus-desktop".to_string()));
458	                    }
459	                    #[cfg(not(target_arch = "wasm32"))]
460	                    {
461	                        let debug_port = {
462	                            let inner = app_state_init
463	                                .inner
464	                                .lock()
465	                                .expect("invariant: app state mutex not poisoned");
466	                            inner
467	                                .services
468	                                .as_ref()
469	                                .and_then(|s| s.config.debug.resolve_debug_server())
470	                        };
471	                        if let Some(port) = debug_port {
472	                            let (screenshot_tx, screenshot_rx) = debug_server::screenshot_channel();
473	                            let app_for_debug = app_state_init.clone();
474	                            spawn(async move {
475	                                debug_server::run(app_for_debug, port, screenshot_tx).await;
476	                            });
477	                            spawn(screenshot_bridge(screenshot_rx));
478	                        }
479	                    }
480	                    info!("后端初始化完成");
481	                    init_phase.set(InitPhase::Ready);
482	                }
483	                Err(e) => {
484	                    error!(error = %e, "后端初始化失败");
485	                    init_phase.set(InitPhase::Error(e.to_string()));
486	                }
487	            }
488	        });
489	    });
490	
491	    // Tick loop：~30 FPS
492	    let app_state_tick = app_state.clone();
493	    use_hook(move || {
494	        spawn(async move {
495	            loop {
496	                tokio::time::sleep(Duration::from_millis(33)).await;
497	                if let Ok(mut inner) = app_state_tick.inner.lock() {
498	                    inner.process_tick(1.0 / 30.0);
499	                    render_state.set(inner.render_state.clone());
500	                }
501	            }
502	        });
503	    });
504	
505	    // 键盘绑定：JS 监听 → dioxus.send() → Rust recv() 处理
506	    let app_state_keys = app_state.clone();
507	    use_hook(move || {
508	        spawn(async move {
509	            let mut eval = document::eval(
510	                r#"
511	                document.addEventListener("keydown", function(e) {
512	                    dioxus.send({ type: "down", key: e.key, code: e.code });
513	                    if (["Escape", " ", "Enter", "Control", "Backspace"].includes(e.key)) {
514	                        e.preventDefault();
515	                    }
516	                });
517	                document.addEventListener("keyup", function(e) {
518	                    dioxus.send({ type: "up", key: e.key, code: e.code });
519	                });
520	                "#,
521	            );
522	
523	            loop {
524	                let msg: Result<serde_json::Value, _> = eval.recv().await;
525	                let Ok(msg) = msg else { break };
526	
527	                let event_type = msg.get("type").and_then(|v| v.as_str()).unwrap_or("");
528	                let key = msg.get("key").and_then(|v| v.as_str()).unwrap_or("");
529	
530	                if let Ok(mut inner) = app_state_keys.inner.lock() {
531	                    match (event_type, key) {
532	                        ("down", "Escape") => {
533	                            let screen = inner.render_state.host_screen.clone();
534	                            match screen {
535	                                HostScreen::InGame => {
536	                                    inner.set_host_screen(HostScreen::InGameMenu);
537	                                }
538	                                HostScreen::InGameMenu
539	                                | HostScreen::Save
540	                                | HostScreen::Load
541	                                | HostScreen::Settings
542	                                | HostScreen::History => {
543	                                    inner.set_host_screen(HostScreen::InGame);
544	                                }
545	                                HostScreen::Title => {}
546	                            }
547	                        }
548	                        ("down", " " | "Enter")
549	                            if inner.render_state.host_screen == HostScreen::InGame =>
550	                        {
551	                            inner.process_click();
552	                        }
553	                        ("down", "Control")
554	                            if inner.render_state.host_screen == HostScreen::InGame =>
555	                        {
556	                            inner.set_playback_mode(render_state::PlaybackMode::Skip);
557	                        }
558	                        ("up", "Control")
559	                            if inner.playback_mode == render_state::PlaybackMode::Skip =>
560	                        {
561	                            inner.set_playback_mode(render_state::PlaybackMode::Normal);
562	                        }
563	                        ("down", "a" | "A")
564	                            if inner.render_state.host_screen == HostScreen::InGame =>
565	                        {
566	                            let mode = if inner.playback_mode == render_state::PlaybackMode::Auto {
567	                                render_state::PlaybackMode::Normal
568	                            } else {
569	                                render_state::PlaybackMode::Auto
570	                            };
571	                            inner.set_playback_mode(mode);
572	                        }
573	                        ("down", "Backspace")
574	                            if inner.render_state.host_screen == HostScreen::InGame =>
575	                        {
576	                            inner.restore_snapshot();
577	                        }
578	                        _ => {}
579	                    }
580	                }
581	            }
582	        });
583	    });
584	
585	    // 根据初始化阶段和 host_screen 路由渲染
586	    let phase = init_phase.read().clone();
587	    match phase {
588	        InitPhase::Loading => {
589	            rsx! {
590	                div { class: "game-container",
591	                    div { class: "screen-loading", "Loading..." }
592	                }
593	            }
594	        }
595	        InitPhase::Error(msg) => {
596	            rsx! {
597	                div { class: "game-container",
598	                    div { class: "screen-error", "{msg}" }
599	                }
600	            }
601	        }
602	        InitPhase::Ready => {
603	            let screen = render_state.read().host_screen.clone();
604	            rsx! {
605	                div { class: "game-container",
606	                    match screen {
607	                        HostScreen::Title => rsx! { TitleScreen { render_state } },
608	                        HostScreen::InGame => rsx! {
609	                            VNScene { render_state }
610	                            SkipIndicator { render_state }
611	                        },
612	                        HostScreen::InGameMenu => rsx! {
613	                            VNScene { render_state }
614	                            InGameMenu { render_state }
615	                        },
616	                        HostScreen::Save | HostScreen::Load => rsx! {
617	                            SaveLoadScreen { render_state }
618	                        },
619	                        HostScreen::Settings => rsx! {
620	                            SettingsScreen { render_state }
621	                        },
622	                        HostScreen::History => rsx! {
623	                            HistoryScreen { render_state }
624	                        },
625	                    }
626	                    // 确认弹窗（z-index 最高，覆盖所有页面）
627	                    ConfirmDialog {}
628	                    // Toast 提示（右上角）
629	                    ToastLayer {}
630	                }
631	            }
632	        }
633	    }
634	}
