use std::collections::HashMap;

use ring_resources::manifest::Manifest;
use vn_runtime::command::{Command, Position, Transition};

use super::*;
use crate::render_state::RenderState;

fn setup() -> (CommandExecutor, RenderState, Manifest) {
    (
        CommandExecutor::new(),
        RenderState::new(),
        Manifest::with_defaults(),
    )
}

#[test]
fn show_text_sets_dialogue() {
    let (mut exec, mut rs, manifest) = setup();
    let cmd = Command::ShowText {
        speaker: Some("Alice".to_string()),
        content: "Hello world".to_string(),
        inline_effects: vec![],
        no_wait: false,
    };
    let result = exec.execute(&cmd, &mut rs, &manifest);
    assert_eq!(result, ExecuteResult::WaitForClick);
    let dialogue = rs.dialogue.expect("dialogue should be set");
    assert_eq!(dialogue.speaker.as_deref(), Some("Alice"));
    assert_eq!(dialogue.content, "Hello world");
}

#[test]
fn show_background_with_dissolve_sets_transition() {
    let (mut exec, mut rs, manifest) = setup();
    rs.set_background("bg/old.png".to_string());
    let cmd = Command::ShowBackground {
        path: "bg/new.png".to_string(),
        transition: Some(Transition::simple("dissolve")),
    };
    exec.execute(&cmd, &mut rs, &manifest);
    assert_eq!(rs.current_background.as_deref(), Some("bg/new.png"));
    let bt = rs.background_transition.expect("should be set");
    assert_eq!(bt.old_background.as_deref(), Some("bg/old.png"));
}

#[test]
fn show_character_adds_to_visible() {
    let (mut exec, mut rs, manifest) = setup();
    let cmd = Command::ShowCharacter {
        path: "char/alice/normal.png".to_string(),
        alias: "alice".to_string(),
        position: Position::Center,
        transition: None,
    };
    exec.execute(&cmd, &mut rs, &manifest);
    assert!(rs.visible_characters.contains_key("alice"));
}

#[test]
fn play_bgm_produces_audio_command() {
    let (mut exec, mut rs, manifest) = setup();
    let cmd = Command::PlayBgm {
        path: "bgm/theme.ogg".to_string(),
        looping: true,
    };
    exec.execute(&cmd, &mut rs, &manifest);
    assert!(matches!(
        exec.last_output.audio_command,
        Some(AudioCommand::PlayBgm { .. })
    ));
}

// ── resolve_transition ──────────────────────────────────────────────────

#[test]
fn resolve_transition_dissolve_has_default_duration() {
    let t = Transition::simple("dissolve");
    let (kind, dur) = resolve_transition(&t);
    assert!(matches!(kind, TransitionKind::Dissolve));
    assert!((dur - 0.3).abs() < f32::EPSILON);
}

#[test]
fn resolve_transition_fade_has_default_duration() {
    let t = Transition::simple("fade");
    let (kind, dur) = resolve_transition(&t);
    assert!(matches!(kind, TransitionKind::Fade));
    assert!((dur - 0.5).abs() < f32::EPSILON);
}

#[test]
fn resolve_transition_fadewhite() {
    let t = Transition::simple("fadewhite");
    let (kind, _) = resolve_transition(&t);
    assert!(matches!(kind, TransitionKind::FadeWhite));
}

#[test]
fn resolve_transition_move_or_slide() {
    for name in &["move", "slide"] {
        let t = Transition::simple(*name);
        let (kind, dur) = resolve_transition(&t);
        assert!(matches!(kind, TransitionKind::Move));
        assert!((dur - 0.3).abs() < f32::EPSILON);
    }
}

#[test]
fn resolve_transition_none() {
    let t = Transition::simple("none");
    let (kind, dur) = resolve_transition(&t);
    assert!(matches!(kind, TransitionKind::None));
    assert_eq!(dur, 0.0);
}

#[test]
fn resolve_transition_rule_with_mask_reversed_ramp() {
    use vn_runtime::command::TransitionArg;
    let t = Transition {
        name: "rule".to_string(),
        args: vec![
            (
                Some("mask".to_string()),
                TransitionArg::String("mask.png".to_string()),
            ),
            (Some("reversed".to_string()), TransitionArg::Bool(true)),
            (Some("ramp".to_string()), TransitionArg::Number(0.2)),
        ],
    };
    let (kind, dur) = resolve_transition(&t);
    assert!(matches!(kind, TransitionKind::Rule { .. }));
    if let TransitionKind::Rule {
        mask_path,
        reversed,
        ramp,
    } = kind
    {
        assert_eq!(mask_path, "mask.png");
        assert!(reversed);
        assert!((ramp - 0.2).abs() < f32::EPSILON);
    }
    assert!((dur - 0.5).abs() < f32::EPSILON);
}

#[test]
fn resolve_transition_unknown_falls_back_to_dissolve() {
    let t = Transition::simple("unknown_effect");
    let (kind, dur) = resolve_transition(&t);
    assert!(matches!(kind, TransitionKind::Dissolve));
    assert!((dur - 0.3).abs() < f32::EPSILON);
}

#[test]
fn resolve_transition_custom_duration() {
    use vn_runtime::command::TransitionArg;
    let t = Transition {
        name: "dissolve".to_string(),
        args: vec![(None, TransitionArg::Number(2.0))],
    };
    let (_, dur) = resolve_transition(&t);
    assert!((dur - 2.0).abs() < f32::EPSILON);
}

// ── ShowBackground / ChangeScene ────────────────────────────────────────

#[test]
fn show_background_without_transition() {
    let (mut exec, mut rs, manifest) = setup();
    let cmd = Command::ShowBackground {
        path: "bg/room.png".to_string(),
        transition: None,
    };
    let result = exec.execute(&cmd, &mut rs, &manifest);
    assert_eq!(result, ExecuteResult::Ok);
    assert_eq!(rs.current_background.as_deref(), Some("bg/room.png"));
    assert!(rs.background_transition.is_none());
}

#[test]
fn show_background_with_none_transition() {
    let (mut exec, mut rs, manifest) = setup();
    let cmd = Command::ShowBackground {
        path: "bg/room.png".to_string(),
        transition: Some(Transition::simple("none")),
    };
    let result = exec.execute(&cmd, &mut rs, &manifest);
    assert_eq!(result, ExecuteResult::Ok);
    assert_eq!(rs.current_background.as_deref(), Some("bg/room.png"));
    assert!(rs.background_transition.is_none());
}

#[test]
fn change_scene_with_fade_transition_sets_scene_transition() {
    let (mut exec, mut rs, manifest) = setup();
    rs.set_background("bg/old.png".to_string());
    let cmd = Command::ChangeScene {
        path: "bg/new.png".to_string(),
        transition: Some(Transition::simple("fade")),
    };
    exec.execute(&cmd, &mut rs, &manifest);
    assert_eq!(rs.current_background.as_deref(), Some("bg/old.png"));
    let st = rs.scene_transition.expect("scene transition should be set");
    assert!(matches!(st.transition_type, SceneTransitionKind::Fade));
    assert_eq!(st.pending_background.as_deref(), Some("bg/new.png"));
}

#[test]
fn change_scene_with_fadewhite_transition() {
    let (mut exec, mut rs, manifest) = setup();
    let cmd = Command::ChangeScene {
        path: "bg/bloom.png".to_string(),
        transition: Some(Transition::simple("fadewhite")),
    };
    exec.execute(&cmd, &mut rs, &manifest);
    assert!(matches!(
        rs.scene_transition.expect("should be set").transition_type,
        SceneTransitionKind::FadeWhite
    ));
}

#[test]
fn change_scene_with_rule_transition() {
    use vn_runtime::command::TransitionArg;
    let t = Transition {
        name: "rule".to_string(),
        args: vec![
            (
                Some("mask".to_string()),
                TransitionArg::String("circle.png".to_string()),
            ),
            (None, TransitionArg::Number(1.5)),
        ],
    };
    let cmd = Command::ChangeScene {
        path: "bg/target.png".to_string(),
        transition: Some(t),
    };
    let (mut exec, mut rs, manifest) = setup();
    exec.execute(&cmd, &mut rs, &manifest);
    assert!(matches!(
        rs.scene_transition.expect("should be set").transition_type,
        SceneTransitionKind::Rule { .. }
    ));
}

#[test]
fn change_scene_without_transition() {
