// ── resolve_transition ──────────────────────────────────────────────────

#[test]
fn resolve_transition_dissolve_has_default_duration() {
    let t = Transition::simple("dissolve");
    let (kind, dur) = resolve_transition(&t);
    assert!(matches!(kind, TransitionKind::Dissolve));
    assert!((dur - 0.3).abs() < f32::EPSILON);
}

#[test]
fn resolve_transition_fade_has_default_duration() {
    let t = Transition::simple("fade");
    let (kind, dur) = resolve_transition(&t);
    assert!(matches!(kind, TransitionKind::Fade));
    assert!((dur - 0.5).abs() < f32::EPSILON);
}

#[test]
fn resolve_transition_fadewhite() {
    let t = Transition::simple("fadewhite");
    let (kind, _) = resolve_transition(&t);
    assert!(matches!(kind, TransitionKind::FadeWhite));
}

#[test]
fn resolve_transition_move_or_slide() {
    for name in &["move", "slide"] {
        let t = Transition::simple(*name);
        let (kind, dur) = resolve_transition(&t);
        assert!(matches!(kind, TransitionKind::Move));
        assert!((dur - 0.3).abs() < f32::EPSILON);
    }
}

#[test]
fn resolve_transition_none() {
    let t = Transition::simple("none");
    let (kind, dur) = resolve_transition(&t);
    assert!(matches!(kind, TransitionKind::None));
    assert_eq!(dur, 0.0);
}

#[test]
fn resolve_transition_rule_with_mask_reversed_ramp() {
    use vn_runtime::command::TransitionArg;
    let t = Transition {
        name: "rule".to_string(),
        args: vec![
            (
                Some("mask".to_string()),
                TransitionArg::String("mask.png".to_string()),
            ),
            (Some("reversed".to_string()), TransitionArg::Bool(true)),
            (Some("ramp".to_string()), TransitionArg::Number(0.2)),
        ],
    };
    let (kind, dur) = resolve_transition(&t);
    assert!(matches!(kind, TransitionKind::Rule { .. }));
    if let TransitionKind::Rule {
        mask_path,
        reversed,
        ramp,
    } = kind
    {
        assert_eq!(mask_path, "mask.png");
        assert!(reversed);
        assert!((ramp - 0.2).abs() < f32::EPSILON);
    }
    assert!((dur - 0.5).abs() < f32::EPSILON);
}

#[test]
fn resolve_transition_unknown_falls_back_to_dissolve() {
    let t = Transition::simple("unknown_effect");
    let (kind, dur) = resolve_transition(&t);
    assert!(matches!(kind, TransitionKind::Dissolve));
    assert!((dur - 0.3).abs() < f32::EPSILON);
}

#[test]
fn resolve_transition_custom_duration() {
    use vn_runtime::command::TransitionArg;
    let t = Transition {
        name: "dissolve".to_string(),
        args: vec![(None, TransitionArg::Number(2.0))],
    };
    let (_, dur) = resolve_transition(&t);
    assert!((dur - 2.0).abs() < f32::EPSILON);
}

