/// VN 场景包装器：组合 ring-render 的 VNSceneCore 与 app 级组件。
///
/// 将 AppState 交互通过 EventHandler 回调传递给 VNSceneCore，
/// 并注入 QuickMenu / MapOverlay / MinigameOverlay 等 app 级组件。
#[component]
pub fn VNScene(render_state: Signal<RenderState>) -> Element {
    let app_state = use_context::<AppState>();

    let app_click = app_state.clone();
    let app_choose = app_state.clone();
    let app_cutscene = app_state.clone();

    rsx! {
        VNSceneCore {
            render_state,
            on_scene_click: move |_| {
                if let Ok(mut inner) = app_click.inner.lock() {
                    inner.process_click();
                }
            },
            on_choose: move |idx: usize| {
                if let Ok(mut inner) = app_choose.inner.lock() {
                    inner.process_choose(idx);
                }
            },
            on_cutscene_end: move |_| {
                if let Ok(mut inner) = app_cutscene.inner.lock() {
                    inner.finish_cutscene();
                }
            },
            // app 级组件通过 children slot 注入
            QuickMenu { render_state }
            MapOverlay { render_state }
            MinigameOverlay { render_state }
        }
    }
}

