151	    // ── 小游戏完成端点（iframe 导航触发） ──
152	    if path_clean.starts_with("__game_complete") {
153	        let query = request.uri().query().unwrap_or("");
154	        let result = query
155	            .split('&')
156	            .find_map(|kv| {
157	                let (k, v) = kv.split_once('=')?;
158	                (k == "result").then(|| percent_decode(v))
159	            })
160	            .unwrap_or_default();
161	        tracing::debug!(result = %result, "game complete via ring-asset");
162	        if let Ok(mut slot) = GAME_COMPLETE_RESULT.lock() {
163	            *slot = Some(result);
164	        }
165	        // 纯黑空页面，与覆盖层背景一致，无视觉闪烁
166	        let body = br#"<!DOCTYPE html><html><body style="background:#000;margin:0"></body></html>"#;
167	        return http::Response::builder()
168	            .status(200)
169	            .header("Content-Type", "text/html")
170	            .body(Cow::from(body.to_vec()))
171	            .unwrap();
172	    }
173	
174	    // ── 虚拟 engine-sdk.js（兼容游戏显式 <script src="../../engine-sdk.js"> 加载） ──
175	    if path_clean == "engine-sdk.js" {
176	        return http::Response::builder()
177	            .status(200)
178	            .header("Content-Type", "application/javascript")
179	            .header("Access-Control-Allow-Origin", "*")
180	            .body(Cow::from(GAME_ENGINE_SDK_JS.as_bytes().to_vec()))
181	            .unwrap();
182	    }
183	
184	    let logical_path = LogicalPath::new(&path_clean);
185	
186	    tracing::debug!(uri = %uri, path = %logical_path, "ring-asset request");
187	
188	    #[expect(
189	        clippy::expect_used,
190	        reason = "uninitialised RM is an engine invariant violation"
191	    )]
192	    let rm = RESOURCE_MANAGER
193	        .get()
194	        .expect("invariant: ResourceManager not yet initialized when ring-asset request arrived");
195	
196	    let mime = guess_mime(&path_clean);
197	
198	    match rm.read_bytes(&logical_path) {
199	        Ok(bytes) => {
200	            // games/*/**.html: 自动注入 engine JS SDK（postMessage 桥接）
201	            let body = if path_clean.starts_with("games/") && mime == "text/html" {
202	                let html = String::from_utf8_lossy(&bytes);
203	                let injected = inject_engine_sdk(&html);
204	                Cow::from(injected.into_bytes())
205	            } else {
206	                Cow::from(bytes)
207	            };
208	            http::Response::builder()
209	                .status(200)
210	                .header("Content-Type", mime)
211	                .header("Access-Control-Allow-Origin", "*")
212	                .body(body)
213	                .unwrap()
214	        }
215	        Err(e) => {
216	            tracing::warn!(path = %logical_path, error = %e, "ring-asset 404");
217	            http::Response::builder()
218	                .status(404)
219	                .header("Content-Type", "text/plain")
220	                .body(Cow::from(format!("Not Found: {logical_path}").into_bytes()))
221	                .unwrap()
222	        }
223	    }
224	}
