use dioxus::prelude::*;

use super::{
    audio_bridge::AudioBridge, background::BackgroundLayer, chapter_mark::ChapterMark,
    character::CharacterLayer, choice::ChoicePanel, dialogue::DialogueBox, nvl::NvlPanel,
    rule_transition::RuleTransitionCanvas, title_card::TitleCard, transition::TransitionOverlay,
    video::VideoOverlay,
};
use crate::render_state::{PlaybackMode, RenderState};

/// VN 场景核心容器：组合所有共享渲染层。
///
/// 处理场景级效果（shake/blur/dim）和 skip-mode 切换。
/// 交互事件通过 `EventHandler` 回调传出，由宿主 app 处理。
/// 宿主可通过 `children` slot 注入 app 级组件（QuickMenu、MapOverlay 等）。
#[component]
pub fn VNSceneCore(
    render_state: Signal<RenderState>,
    on_scene_click: EventHandler<()>,
    on_choose: EventHandler<usize>,
    on_cutscene_end: EventHandler<()>,
    children: Element,
) -> Element {
    let rs = render_state.read();

    // 场景效果：shake 偏移 + blur + dim
    let se = &rs.scene_effect;
    let scene_transform = if se.shake_offset_x != 0.0 || se.shake_offset_y != 0.0 {
        format!(
            "transform: translate({}px, {}px);",
            se.shake_offset_x, se.shake_offset_y
        )
    } else {
        String::new()
    };
    let scene_filter = if se.blur_amount > 0.0 {
        format!("filter: blur({}px);", se.blur_amount)
    } else {
        String::new()
    };
    let scene_style = format!("{scene_transform} {scene_filter}");

    // dim 覆盖层
    let dim_level = se.dim_level;

    // skip-mode class
    let skip_class = if rs.playback_mode == PlaybackMode::Skip {
        " skip-mode"
    } else {
        ""
    };

    rsx! {
        div {
            class: "vn-scene{skip_class}",
            onclick: move |_| {
                on_scene_click.call(());
            },

            // 场景效果包装层
            div {
                class: "vn-scene__layers",
                style: "{scene_style}",

                BackgroundLayer { render_state }
                CharacterLayer { render_state }
                TransitionOverlay { render_state }
                RuleTransitionCanvas { render_state }
            }

            // dim 覆盖层
            if dim_level > 0.0 {
                div {
                    class: "vn-scene__dim",
                    style: "opacity: {dim_level};",
                }
            }

            DialogueBox { render_state }
            NvlPanel { render_state }
            ChoicePanel { render_state, on_choose }
            ChapterMark { render_state }
            TitleCard { render_state }
            VideoOverlay { render_state, on_cutscene_end }
            AudioBridge { render_state }
            {children}
        }
    }
}

